# Both remaining tiles are visible under separate hands; use synchronized guarded moves to save actions.
# Pinch the lower loop of 3 and the central stroke of 2, then verify both after lifting.
def move_pair(left_xyz, right_xyz, lg, rg, count):
    global obs, steps_left, halted, motion_fault
    if halted or motion_fault:
        return False
    starts = {arm: np.array(obs['state'][arm + '_ee_pose']) for arm in ['left','right']}
    goals = {'left': np.array(list(left_xyz) + q_down), 'right': np.array(list(right_xyz) + q_down)}
    for j in range(min(count, steps_left)):
        alpha = min(1.0, (j+1)/max(1,count-4))
        action = {'left_ee_joint_state':[lg], 'right_ee_joint_state':[rg]}
        for arm in ['left','right']:
            p = starts[arm]*(1-alpha) + goals[arm]*alpha
            p[3:] = p[3:]/np.linalg.norm(p[3:])
            action[arm+'_ee_pose'] = p
        obs, reward, terminated, truncated, info = step(action)
        steps_left -= 1
        halted = terminated or truncated or bool(info.get('success',False))
        if halted:
            break
        for arm in ['left','right']:
            actual = np.array(obs['state'][arm+'_ee_pose'])
            error = np.linalg.norm(actual[:3] - action[arm+'_ee_pose'][:3])
            if error > 0.06:
                motion_fault = True
        if motion_fault:
            break
    print('pair', 'remaining',steps_left,'fault',motion_fault,'halted',halted)
    print(obs['state'])
    return not motion_fault
